INSERT OR IGNORE INTO categories (name, color1, color2, sort, updated_at) VALUES ('Life', '#e2f5dc', '#ade0bf', 2, 1767225600000);
INSERT OR IGNORE INTO categories (name, color1, color2, sort, updated_at) VALUES ('Character', '#dfeafc', '#abc8f2', 3, 1767225600000);
INSERT OR IGNORE INTO categories (name, color1, color2, sort, updated_at) VALUES ('Art', '#fff0cc', '#f9c39a', 4, 1767225600000);
