INSERT OR IGNORE INTO categories (name, color1, color2, sort, updated_at) VALUES ('Misc', '#eeeef3', '#cfcfdc', 7, 1767225600000);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('937330aa-8749-419d-8868-da977c64458e', 'And there''s nothing wrong with being a lizard either. Unless you were born to be a hawk.', 'Baghra', 'Shadow and Bone', 'Leigh Bardugo', 'Identity', 1767225600000, 1767225600000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('3bda4700-b515-457b-835d-56410f18c1bd', 'But that one moment holding the quarterstaff sang to him. A single moment of clarity in an otherwise confusing world.', '', 'The Way of Kings', 'Brandon Sanderson', 'Identity', 1767225601000, 1767225601000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('d325fd30-15bb-420f-81ac-4dfe4472f555', 'Sometimes we find it hardest to accept in others that which we cling to in ourselves.', 'Jasnah Kholin', 'The Way of Kings', 'Brandon Sanderson', 'Identity', 1767225602000, 1767225602000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('aa1b4f73-419f-429f-b386-77f6c91fe9cc', 'Expectation wasn''t just about what people expected of you. It was about what you expected of yourself.', '', 'Words of Radiance', 'Brandon Sanderson', 'Identity', 1767225603000, 1767225603000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('9764eae4-02c6-4867-af40-4767580da691', 'Sometimes a hypocrite is nothing more than a man in the process of changing.', 'Dalinar Kholin', 'Oathbringer', 'Brandon Sanderson', 'Identity', 1767225604000, 1767225604000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('9a28e40b-31f5-4e35-863f-3fe406520665', 'He hadn''t changed in one giant leap, but across a million little steps.', 'Dalinar Kholin', 'Oathbringer', 'Brandon Sanderson', 'Identity', 1767225605000, 1767225605000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('6a2568a2-688f-4279-bd46-6ade34afa709', 'Do not dismiss your own talents because you envy those of another.', '', 'Rhythm of War', 'Brandon Sanderson', 'Identity', 1767225606000, 1767225606000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('7ead39ba-e2b8-4d62-ac53-e3df45c84261', 'Suffering is cheap as clay and twice as common; What matters is what each man makes of it.', 'Baghra', 'Ruin and Rising', 'Leigh Bardugo', 'Feelings', 1767225607000, 1767225607000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('78602b26-18d1-4540-96d9-dd6baea179a2', 'To lack feeling is to be dead, but to act on every feeling is to be a child.', 'Dalinar Kholin', 'The Way of Kings', 'Brandon Sanderson', 'Feelings', 1767225608000, 1767225608000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('99dd4cc4-5ce5-49aa-9314-238ffe52ede3', 'Accept the pain, but don''t accept that you deserved it.', 'Hoid', 'Oathbringer', 'Brandon Sanderson', 'Feelings', 1767225609000, 1767225609000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('0d22ca9d-3002-42b1-bd7d-c2189cd6769c', 'He felt good lots of days. Trouble was, on the bad days, that was hard to remember. At those times, for some reason, he felt like he had always been in that darkness, and always would be.', 'Kaladin', 'Oathbringer', 'Brandon Sanderson', 'Feelings', 1767225610000, 1767225610000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('def745b5-954a-4fb6-9290-871a4f0d4ae2', 'The world is monstrous at times, and there are those who would have you believe that you are terrible by association. I am. No. For you see, it flows the other direction. You are not worse for your association with the world, but it is better for its association with you.', 'Hoid', 'Oathbringer', 'Brandon Sanderson', 'Feelings', 1767225611000, 1767225611000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('e7f853c9-6ff9-46ca-8873-be222a73ef92', 'You''re always willing to give others more charity than you extend yourself.', 'Veil', 'Rhythm of War', 'Brandon Sanderson', 'Feelings', 1767225612000, 1767225612000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('92dc2330-bcc4-491d-a379-cda310116737', 'The quality of our lives is not measured by the amount of time we spend in a state of perfection.', '', 'Burnout - The Secret to Unlocking the Stress Cycle', 'Emily and Amelia Nagoski', 'Life', 1767225613000, 1767225613000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('3f1462b6-043d-47c0-88bf-041ca707a09f', 'Life before Death. Strength before Weakness. Journey before Destination.', '', 'The Way of Kings', 'Brandon Sanderson', 'Life', 1767225614000, 1767225614000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('3f4f3c4b-cbee-4443-b745-f57fbccbb569', 'There is no greater indication of youth, perhaps, than the desire for everything to be as it should.', 'Jasnah Kholin', 'The Way of Kings', 'Brandon Sanderson', 'Life', 1767225615000, 1767225615000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('e042fe94-b8c0-488c-9957-8e9f24734a54', 'To be human is to seek beauty, Shallan. Do not despair, do not end the hunt because thorns grow in your way.', 'Hoid', 'Words of Radiance', 'Brandon Sanderson', 'Life', 1767225616000, 1767225616000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('3f115bd5-57c0-4860-98ec-785f4b0b6a49', 'You tried to help the people of the market. You mostly failed. This is life. The longer you live, the more you fail. Failure is the mark of a life well lived. In turn, the only way to live without failure is to be of no use to anyone. Trust me, I''ve practiced.', 'Hoid', 'Oathbringer', 'Brandon Sanderson', 'Life', 1767225617000, 1767225617000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('3aa19250-37b5-4328-9ff5-e80e6007b178', 'Life breaks us, Teft. Then we fill the cracks with something stronger.', 'Phendorana', 'Oathbringer', 'Brandon Sanderson', 'Life', 1767225618000, 1767225618000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('6e568e4e-485f-4a37-b67a-4bac474aeb06', 'The trick to happiness wasn’t in freezing every momentary pleasure and clinging to each one, but in ensuring one’s life would produce many future moments to anticipate.', 'Shallan Davar', 'Oathbringer', 'Brandon Sanderson', 'Life', 1767225619000, 1767225619000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('f10e643d-41fa-4522-b5bc-383fc37796b7', 'The most important word a man can say are, "I will do better.”', 'Dalinar Kholin', 'Oathbringer', 'Brandon Sanderson', 'Life', 1767225620000, 1767225620000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('efd0621e-a75a-413c-a033-226e26ab3c1b', 'You can’t spend forever floating between worlds, Cousin, she thought. Eventually you’ll need to decide where you want to belong. Life was so much harder, but potentially so much more fulfilling, when you found the courage to choose.', 'Jasnah Kholin', 'Oathbringer', 'Brandon Sanderson', 'Life', 1767225621000, 1767225621000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('13b8695a-7990-4f35-9e4c-f82631a4671a', 'You should try to understand what they want out of life, and respect that, rather than projecting onto them what you think they should want out of life.', 'Kaladin', 'Oathbringer', 'Brandon Sanderson', 'Life', 1767225622000, 1767225622000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('ca756b24-2ffc-448f-9ffb-95d4f9dd9d25', 'It will, Wit said, but then it will get better. Then it will get worse again. Then better. This is life, and I will not lie by saying every day will be sunshine. But there will be sunshine again, and that is a very different thing to say. That is truth. I promise you, Kaladin: You will be warm again.', 'Hoid', 'Rhythm of War', 'Brandon Sanderson', 'Life', 1767225623000, 1767225623000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('b11b18d0-9826-4542-a225-cadfa7b8b1bc', 'Go to bed; tired is stupid.', 'Kurremkarmerruk', 'A Wizard of Earthsea', 'Ursula K. Le Guin', 'Life', 1767225624000, 1767225624000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('2a765a31-196b-4a5a-a57d-68bef091b08b', 'So laying eggs all your life and then getting plucked, stuffed and roasted is good enough for you, is it?', 'Ginger', 'Chicken run', '', 'Life', 1767225625000, 1767225625000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('5cd61eb2-ceb8-4738-8943-8a622d122b4b', 'Ginger: So laying eggs all your life and then getting plucked, stuffed and roasted is good enough for you, is it?
Babs: It''s a livin''.', '', 'Chicken run', '', 'Life', 1767225626000, 1767225626000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('cb873396-d99c-4fc1-b797-f2d6e83c0a82', 'The condition of all who are preoccupied is wretched, but most wretched is the condition of those who labor at preoccupations that are not even their own.', '', 'On the Shortness of Life 1.19', 'Seneca', 'Life', 1767225627000, 1767225627000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('c3f51bc7-667c-4f17-a674-c67ba8b43a0f', 'Whatever comes, face it on your feet.', 'Lan', 'The Great Hunt', 'Robert Jordan', 'Life', 1767225628000, 1767225628000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('0e26e247-cf9e-4b26-9c9b-3c16a9af2234', 'We say we are scared by failure, but what frightens us more is the possibility of success.', '', 'The Artist''s Way', 'Julia Cameron', 'Life', 1767225629000, 1767225629000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('fa2023b2-518d-40f7-854c-6bba4dcbdd60', 'Somebody has to start. Somebody has to step forward and do what is right, because it is right.', 'Lirin', 'The Way of Kings', 'Brandon Sanderson', 'Character', 1767225630000, 1767225630000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('c6531262-8586-4b37-947f-6f20897312a8', 'Power was an illusion of perception, as Jasnah had said. The first step to being in control was to see yourself as capable of being in control.', '', 'Oathbringer', 'Brandon Sanderson', 'Character', 1767225631000, 1767225631000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('2a0e11ed-fbe3-4954-8e7e-aa0417f01d8f', 'Who do you think is stronger? The man who has walked easily his entire life, or the man with no legs? The man who must pull himself by his arms?', 'Adolin Kholin', 'Rhythm of War', 'Brandon Sanderson', 'Character', 1767225632000, 1767225632000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('48da1a1d-0b6c-455e-82be-bdd63553d9a2', 'Few men have the wisdom to realize when they need help. Fewer still have the strength to go get it.', '', 'Rhythm of War', 'Brandon Sanderson', 'Character', 1767225633000, 1767225633000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('3d42730b-df74-4a11-9152-94717af84054', 'Strength could be a matter of perception sometimes. And today Shallan found she could choose strength.', '', 'Wind and Truth', 'Brandon Sanderson', 'Character', 1767225634000, 1767225634000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('34746556-2398-4e62-b122-fd9a3fd876cc', 'A virtue is something that is valuable even if it gives you nothing. A virtue persists without payment or compensation.', 'Hoid', 'Wind and Truth', 'Brandon Sanderson', 'Character', 1767225635000, 1767225635000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('cc4f7a79-c35e-4616-9bbd-43c997689c54', 'Remember the flame, lad, and the void.', 'Tam al’Thor', 'The Eye of the World', 'Robert Jordan', 'Character', 1767225636000, 1767225636000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('39811a4a-401b-4ef2-b85f-c19e6d460762', 'We are always more afraid than we wish to be, but we can always be braver than we expect.', 'Sorilea', 'Lord of Chaos', 'Robert Jordan', 'Character', 1767225637000, 1767225637000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('b6c4d08c-fced-49d6-961f-47b3883c174a', 'You cannot create a piece of art merely for money. Doing it as part of commerce so denudes art of wonder that it ceases to be art.', '', 'Linchpin', 'Seth Godin', 'Art', 1767225638000, 1767225638000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('c196f2b9-c1bb-495a-8d47-985f3bf56c18', 'The purpose of a storyteller is not to tell you how to think, but to give you questions to think upon.', '', 'The Way of Kings', 'Brandon Sanderson', 'Art', 1767225639000, 1767225639000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('ee6c7505-aac4-41b6-ba58-9f1176809617', 'Beauty was out there, all around. To create art was not to capture it, but to participate in it.', '', 'Words of Radiance', 'Brandon Sanderson', 'Art', 1767225640000, 1767225640000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('acc495e5-7de0-4d9e-af8b-1d4b816ac1ea', 'If you could explain something perfectly, then you’d never need art.', 'Hoid', 'Oathbringer', 'Brandon Sanderson', 'Art', 1767225641000, 1767225641000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('659ccb0f-1a7d-4f00-9d7e-68f9637756de', 'Have you ever considered, bridgeman, that bad art does more for the world than good art? Artists spend more of their lives making bad practice pieces than they do masterworks, particularly at the start. And even when an artist becomes a master, some pieces don’t work out. Still others are somehow just wrong until the last stroke. You learn more from bad art than you do from good art, as your mistakes are more important than your successes. Plus, good art usually evokes the same emotions in people—most good art is the same kind of good. But bad pieces can each be bad in their own unique way. So I’m glad we have bad art, and I’m sure the Almighty agrees.', 'Hoid', 'Oathbringer', 'Brandon Sanderson', 'Art', 1767225642000, 1767225642000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('c665b2d4-6475-4329-83ba-fc1dd0fd9305', 'Art is not art if it has a function.', '', 'Oathbringer', 'Brandon Sanderson', 'Art', 1767225643000, 1767225643000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('dcca724b-1d1d-4f97-8647-1391cd8db92a', 'I am an artist, Wit said. I should thank you not to demean me by insisting my art must be trying to accomplish something. In fact, you shouldn’t enjoy art. You should simply admit that it exists, then move on. Anything else is patronizing.', 'Hoid', 'Rhythm of War', 'Brandon Sanderson', 'Art', 1767225644000, 1767225644000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('6b61619f-68e7-47c1-b0f9-22cd611da38c', 'Perhaps the question isn’t ‘What use is art?’ Wit mused. Perhaps even that simple question misses the point. It’s like asking the use of having hands, or walking upright, or growing hair. Art is part of us, Kaladin. That’s the use; that’s the reason. It exists because on some fundamental level we need it. Art exists to be made.', 'Hoid', 'Wind and Truth', 'Brandon Sanderson', 'Art', 1767225645000, 1767225645000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('f00e8a18-4b21-48f2-a712-7de55a642599', 'Nothing is just anything.', 'A gyptian', 'La Belle Sauvage', 'Philip Pullman', 'Reality', 1767225646000, 1767225646000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('f6e60727-a1ce-450d-83aa-9433cc6a8bef', 'Humans can see the world as it is not. It is why your lies can be so strong. You are able to not admit that they are lies.', 'Pattern', 'Words of Radiance', 'Brandon Sanderson', 'Reality', 1767225647000, 1767225647000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('c082b566-e2fd-45de-b25a-5cf006669bdc', 'In my painful experience, the truth may be simple, but it is rarely easy.', 'Dalinar Kholin', 'Oathbringer', 'Brandon Sanderson', 'Reality', 1767225648000, 1767225648000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('c38fa647-6de4-48aa-bd49-b55de0b296ed', '“Inappropriate?” Pattern said. “Such as … dividing by zero?”', 'Pattern', 'Oathbringer', 'Brandon Sanderson', 'Funny', 1767225649000, 1767225649000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('f79ffe5a-ab2d-4486-a5d1-a57a156206fd', 'NO MATING.', 'Pattern', 'Oathbringer', 'Brandon Sanderson', 'Funny', 1767225650000, 1767225650000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('d25fb2fe-8477-4625-9643-22690ecd0927', 'Your name is Lift, right? Right. And your order? More food.', 'Lift', 'Oathbringer', 'Brandon Sanderson', 'Funny', 1767225651000, 1767225651000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('5549d1f1-5e18-4684-8f9c-967683282ef4', 'Journey before destination, you bastard.', '', 'Rhythm of War', 'Brandon Sanderson', 'Funny', 1767225652000, 1767225652000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('c18935f7-6ac0-4d82-af1a-30ce400432e0', 'Evil can be unscrupulous, and good can’t. Evil has nothing to stop it doing what it wants, while good has one hand tied behind its back. To do the things it needs to do to win, it’d have to become evil to do ’em.', 'Farder Coram', 'The Secret Commonwealth', 'Philip Pullman', 'Misc', 1767225653000, 1767225653000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('989dff19-cd2e-42e0-b960-a22419664b6e', 'Expectations were like fine pottery. The harder you held them, the more likely they were to crack.', '', 'The Way of Kings', 'Brandon Sanderson', 'Misc', 1767225654000, 1767225654000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('5a6f7ec7-55bf-4ade-b0c9-e9cf0c2ad4b4', 'Do not let your assumptions about a culture block your ability to perceive the individual, or you will fail.', 'Vstim', 'Words of Radiance', 'Brandon Sanderson', 'Misc', 1767225655000, 1767225655000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('e842cc13-aa21-490a-8dad-21c7653f6546', 'One can believe in a story without believing it happened.', 'Vstim', 'Oathbringer', 'Brandon Sanderson', 'Misc', 1767225656000, 1767225656000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('6006b395-fcfe-460f-b473-703474d21166', 'But merely being tradition does not make something worthy, Kadash. We can''t just assume that because something is old it is right.', 'Dalinar Kholin', 'Oathbringer', 'Brandon Sanderson', 'Misc', 1767225657000, 1767225657000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('3dad37d9-24c0-4f1d-9102-a0a6e250f09f', 'In all the history of mankind, has any conqueror decided they had enough? Has any man just said, ‘This is good. This is what I wanted,’ and gone home?', 'Gavilar Kholin', 'Oathbringer', 'Brandon Sanderson', 'Misc', 1767225658000, 1767225658000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('75930cb6-9783-4ecc-b1e7-eb0af25b7465', 'Turned out that the end of the world had to actually arrive before people would take it seriously.', '', 'Oathbringer', 'Brandon Sanderson', 'Misc', 1767225659000, 1767225659000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('6899d0d5-b267-407e-8631-d73a714231d2', 'You could not arrive at excellence by the average of these people. Excellence was an individual quest, not a group effort.', 'Szeth', 'Oathbringer', 'Brandon Sanderson', 'Misc', 1767225660000, 1767225660000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('0eab86e2-3ba7-4ed1-87f2-09c0a60ea852', 'If nobody asked questions, then we would never learn anything.', 'Hoid', 'Oathbringer', 'Brandon Sanderson', 'Misc', 1767225661000, 1767225661000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('84e960b2-cc4f-45ec-ad97-1cea24e8e323', 'It is not perfection we seek, for perfection is impossible. It is instead consistency.', '', 'Oathbringer', 'Brandon Sanderson', 'Misc', 1767225662000, 1767225662000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('4dd5d62f-92f9-4989-8c70-db8c432ab33b', 'Creativity requires faith. Faith requires that we relinquish control.', '', 'The Artist''s Way', 'Julia Cameron', 'Art', 1767225663000, 1767225663000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('ca1f1d11-610f-497c-8265-378367c125c4', 'Each of us has an inner dream that we can unfold if we will just have the courage to admit what it is.', '', 'The Artist''s Way', 'Julia Cameron', 'Life', 1767225664000, 1767225664000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('4b4e7c15-eed3-4819-b5c7-6c70c3f58524', 'Follow your bliss and doors will open where there were no doors before.', '', '', 'Joseph Campbell', 'Life', 1767225665000, 1767225665000, 0);
INSERT OR IGNORE INTO quotes (id, text, character, book, author, category, created_at, updated_at, deleted) VALUES ('e58f623e-3961-4238-a499-45dfab89f5e1', 'The Wheel of Time turns, and Ages come and pass, leaving memories that become legend. Legend fades to myth, and even myth is long forgotten when the Age that gave it birth comes again. In one Age, called the Third Age by some, an Age yet to come, an Age long past, a wind rose in the Mountains of Mist. The wind was not the beginning. There are neither beginnings nor endings to the turning of the Wheel of Time. But it was a beginning.', '', 'The Eye of the World', 'Robert Jordan', 'Misc', 1767225666000, 1767225666000, 0);
